content:
:root{
  --ink:#0f172a; --ink-2:#334155; --muted:#64748b; --line:#e2e8f0; --line-2:#eef2f7;
  --bg:#f4f6fa; --card:#ffffff;
  --brand:#1d4ed8; --brand-2:#2563eb; --brand-weak:#eff6ff;
  --ok:#16a34a; --ok-weak:#f0fdf4;
  --warn:#d97706; --warn-weak:#fffbeb;
  --danger:#dc2626; --danger-weak:#fef2f2;
  --info:#0e7490; --info-weak:#ecfeff;
  --neutral:#64748b; --neutral-weak:#f1f5f9;
  --in:#059669; --out:#dc2626;
  --sidebar:#0b1730; --sidebar-2:#12224a; --sidebar-ink:#cbd5e1;
  --radius:12px; --radius-sm:8px;
  --shadow:0 1px 2px rgba(15,23,42,.04), 0 4px 16px rgba(15,23,42,.05);
  --shadow-lg:0 12px 40px rgba(15,23,42,.18);
  --font:-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Microsoft YaHei","Helvetica Neue",Arial,sans-serif;
}
*{box-sizing:border-box;margin:0;padding:0}
html,body{height:100%}
body{font-family:var(--font);color:var(--ink);background:var(--bg);font-size:14px;line-height:1.55;-webkit-font-smoothing:antialiased}
button{font-family:inherit;cursor:pointer;border:none;background:none}
input,select{font-family:inherit;font-size:13px}
a{color:var(--brand);text-decoration:none}
.mono{font-variant-numeric:tabular-nums;font-family:"SF Mono",ui-monospace,Consolas,"Roboto Mono",monospace}
.nowrap{white-space:nowrap}
.hint{font-size:12px;color:var(--muted)}
.hidden{display:none!important}

/* ===== 登录页 ===== */
#login{position:fixed;inset:0;display:flex;align-items:center;justify-content:center;background:
 radial-gradient(1200px 600px at 80% -10%,#1e3a8a55,transparent),
 radial-gradient(900px 500px at -10% 110%,#0e749055,transparent),
 linear-gradient(160deg,#0b1730,#0d1f42 60%,#0b1a36);
 color:#fff;z-index:100}
.login-box{width:400px;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.12);border-radius:16px;padding:36px 34px;backdrop-filter:blur(12px)}
.login-box .logo{display:flex;align-items:center;gap:11px;margin-bottom:8px}
.login-box .logo .mark{width:38px;height:38px;border-radius:10px;background:linear-gradient(135deg,#2563eb,#0e7490);display:flex;align-items:center;justify-content:center;font-weight:700;font-size:18px}
.login-box h1{font-size:19px;font-weight:700;letter-spacing:.2px}
.login-box .sub{font-size:13px;color:#cbd5e1;margin:6px 0 24px}
.login-box label{display:block;font-size:12px;color:#cbd5e1;margin:14px 0 6px}
.login-box input{width:100%;padding:11px 13px;border-radius:9px;border:1px solid rgba(255,255,255,.16);background:rgba(255,255,255,.06);color:#fff;outline:none}
.login-box input:focus{border-color:#3b82f6;box-shadow:0 0 0 3px #3b82f655}
.login-box input::placeholder{color:#94a3b8}
.login-btn{width:100%;margin-top:24px;padding:12px;border-radius:9px;background:linear-gradient(135deg,#2563eb,#0e7490);color:#fff;font-weight:600;font-size:14px}
.login-btn:hover{filter:brightness(1.06)}
.login-btn:disabled{opacity:.6;cursor:not-allowed}
.login-error{font-size:12px;color:#fca5a5;margin-top:12px;min-height:16px}
.secure-note{display:flex;align-items:center;gap:7px;margin-top:18px;font-size:12px;color:#94a3b8}
.secure-note .dot{width:7px;height:7px;border-radius:50%;background:#34d399}

/* ===== 布局 ===== */
#app{display:none;height:100%}
#app.on{display:flex}
#sidebar{width:236px;background:var(--sidebar);color:var(--sidebar-ink);display:flex;flex-direction:column;flex-shrink:0}
.side-head{display:flex;align-items:center;gap:10px;padding:20px 18px 16px;border-bottom:1px solid #ffffff14}
.side-head .mark{width:34px;height:34px;border-radius:9px;background:linear-gradient(135deg,#2563eb,#0e7490);display:flex;align-items:center;justify-content:center;font-weight:700;color:#fff;font-size:15px;flex-shrink:0}
.side-head b{color:#fff;font-size:14.5px;display:block;line-height:1.2}
.side-head span{font-size:11px;color:#7d8da6}
.side-nav{padding:12px 10px;flex:1;overflow:auto}
.nav-group{font-size:11px;color:#5f7190;letter-spacing:.05em;padding:14px 10px 5px;text-transform:uppercase}
.nav-item{display:flex;align-items:center;gap:10px;padding:9px 10px;border-radius:8px;color:var(--sidebar-ink);font-size:13.5px;margin-bottom:2px;width:100%;text-align:left}
.nav-item:hover{background:#ffffff0d;color:#fff}
.nav-item.active{background:linear-gradient(135deg,#2563eb,#1d4ed8);color:#fff;font-weight:600}
.nav-item .ico{width:18px;height:18px;flex-shrink:0;opacity:.9;font-size:15px;line-height:18px;text-align:center}
.nav-item .badge{margin-left:auto;background:var(--danger);color:#fff;font-size:10.5px;padding:1px 7px;border-radius:99px;font-weight:700}
.nav-item .badge:empty{display:none}
.side-foot{padding:14px 16px;border-top:1px solid #ffffff14;font-size:12px;color:#7d8da6}
.side-foot .uid{display:flex;align-items:center;gap:8px}
.side-foot .avatar{width:30px;height:30px;border-radius:50%;background:#334155;color:#fff;display:flex;align-items:center;justify-content:center;font-size:12px;flex-shrink:0}
.side-foot .logout{margin-top:12px;width:100%;display:flex;align-items:center;gap:9px;padding:8px 10px;border-radius:8px;color:var(--sidebar-ink);font-size:12.5px}
.side-foot .logout:hover{background:#ffffff0d;color:#fff}

#main{flex:1;display:flex;flex-direction:column;min-width:0}
#topbar{height:56px;background:#fff;border-bottom:1px solid var(--line);display:flex;align-items:center;padding:0 22px;gap:16px;flex-shrink:0}
#topbar .crumb{font-size:15px;font-weight:700}
#topbar .crumb small{font-weight:400;color:var(--muted);margin-left:8px;font-size:12.5px}
#topbar .right{margin-left:auto;display:flex;align-items:center;gap:14px}
.env-tag{font-size:11px;padding:3px 9px;border-radius:6px;background:var(--warn-weak);color:var(--warn);border:1px solid #fde68a;font-weight:600}
.icon-btn{width:34px;height:34px;border-radius:8px;display:flex;align-items:center;justify-content:center;color:var(--muted);position:relative}
.icon-btn:hover{background:var(--neutral-weak)}
.icon-btn .dot{position:absolute;top:7px;right:8px;width:7px;height:7px;border-radius:50%;background:var(--danger)}

#content{flex:1;overflow:auto;padding:22px}
.view{min-height:100%}

/* ===== 卡片/统计 ===== */
.card{background:var(--card);border:1px solid var(--line-2);border-radius:var(--radius);box-shadow:var(--shadow)}
.card-hd{padding:15px 18px;border-bottom:1px solid var(--line-2);display:flex;align-items:center;gap:10px}
.card-hd h3{font-size:14.5px;font-weight:650}
.card-hd .sub{font-size:12px;color:var(--muted)}
.card-hd .right{margin-left:auto;display:flex;align-items:center;gap:8px}
.card-bd{padding:16px 18px}
.stat-row{display:grid;gap:14px;grid-template-columns:repeat(4,1fr);margin-bottom:18px}
.stat{padding:16px 18px;border-radius:var(--radius);background:#fff;border:1px solid var(--line-2);box-shadow:var(--shadow);position:relative;overflow:hidden}
.stat .lbl{font-size:12.5px;color:var(--muted)}
.stat .val{font-size:26px;font-weight:700;margin-top:6px;letter-spacing:-.5px}
.stat .val small{font-size:13px;font-weight:500;color:var(--muted);margin-left:2px}
.stat .delta{font-size:12px;margin-top:5px;color:var(--muted)}
.stat .delta.up{color:var(--in)}
.stat .delta.down{color:var(--out)}
.stat .strip{position:absolute;top:0;left:0;right:0;height:3px}
.stat.gain .strip{background:var(--in)} .stat.pay .strip{background:var(--out)}
.stat.net .strip{background:var(--brand)} .stat.cnt .strip{background:var(--info)}
.grid-2{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.grid-2-1{display:grid;grid-template-columns:1.6fr 1fr;gap:16px}
.grid-3{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.mb16{margin-bottom:16px}
.section-gap{display:flex;flex-direction:column;gap:16px}

/* ===== 表格 ===== */
.tbl-wrap{overflow:auto}
table.tbl{width:100%;border-collapse:collapse;font-size:13px}
.tbl th{position:sticky;top:0;background:#f8fafc;color:var(--muted);font-weight:600;text-align:left;padding:10px 12px;border-bottom:1px solid var(--line);font-size:12px;white-space:nowrap;z-index:1}
.tbl td{padding:10px 12px;border-bottom:1px solid var(--line-2);vertical-align:middle}
.tbl tbody tr:hover td{background:#f8fafc;cursor:pointer}
.tbl tr.checked td{background:#eff6ff}
.amt{font-weight:600;font-variant-numeric:tabular-nums}
.amt.in{color:var(--in)} .amt.out{color:var(--out)}
.dir-tag{display:inline-flex;align-items:center;gap:3px;font-size:12px;font-weight:700}
.dir-tag.in{color:var(--in)} .dir-tag.out{color:var(--out)}
.num{font-variant-numeric:tabular-nums}

/* ===== 徽章 ===== */
.badge{display:inline-flex;align-items:center;gap:5px;font-size:11.5px;padding:2.5px 9px;border-radius:99px;font-weight:600;white-space:nowrap}
.badge::before{content:"";width:6px;height:6px;border-radius:50%;background:currentColor;flex-shrink:0}
.b-wait{background:var(--warn-weak);color:var(--warn)}
.b-pass{background:var(--ok-weak);color:var(--ok)}
.b-low{background:#fff7ed;color:#c2410c}
.b-err{background:var(--danger-weak);color:var(--danger)}
.b-push{background:var(--brand-weak);color:var(--brand)}
.b-reject{background:var(--neutral-weak);color:var(--neutral)}
.b-doing{background:var(--info-weak);color:var(--info)}

/* ===== 控件 ===== */
.btn{display:inline-flex;align-items:center;gap:6px;padding:8px 14px;border-radius:8px;font-size:13px;font-weight:600;border:1px solid transparent;transition:.12s}
.btn:disabled{opacity:.5;cursor:not-allowed}
.btn-pri{background:var(--brand);color:#fff}
.btn-pri:hover:not(:disabled){background:var(--brand-2)}
.btn-ok{background:var(--ok);color:#fff}.btn-ok:hover:not(:disabled){filter:brightness(1.05)}
.btn-ghost{background:#fff;border-color:var(--line);color:var(--ink-2)}
.btn-ghost:hover:not(:disabled){background:#f8fafc}
.btn-danger{background:var(--danger-weak);color:var(--danger);border-color:#fecaca}
.btn-danger:hover:not(:disabled){background:#fee2e2}
.btn-sm{padding:5px 10px;font-size:12px;border-radius:7px}
.link-btn{color:var(--brand);font-weight:600;font-size:12.5px;padding:4px 8px;border-radius:6px}
.link-btn:hover{background:var(--brand-weak)}
.input,.select{padding:8px 12px;border:1px solid var(--line);border-radius:8px;background:#fff;color:var(--ink);outline:none;min-width:130px}
.input:focus,.select:focus{border-color:var(--brand);box-shadow:0 0 0 3px #2563eb22}
.search{display:flex;align-items:center;gap:8px;border:1px solid var(--line);border-radius:8px;padding:0 10px;background:#fff;min-width:230px}
.search input{border:none;outline:none;padding:8px 0;flex:1;width:100%}
.filterbar{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:14px}
.filterbar .right{margin-left:auto;display:flex;gap:8px}

/* checkbox */
.ck{display:inline-flex;align-items:center;gap:8px;cursor:pointer;user-select:none;font-size:12.5px;color:var(--ink-2)}
.ck input{width:15px;height:15px;accent-color:var(--brand);cursor:pointer}

/* ===== 看板 tab ===== */
.tabs{display:flex;gap:6px;background:#e8eef5;padding:4px;border-radius:10px;width:max-content;margin-bottom:18px}
.tabs button{padding:7px 16px;border-radius:8px;font-size:13px;font-weight:600;color:var(--ink-2)}
.tabs button.active{background:#fff;color:var(--brand);box-shadow:var(--shadow)}
.dash{display:none}
.dash.on{display:block}

/* ===== 图表 ===== */
.chart{width:100%;height:auto}
.legend{display:flex;gap:16px;flex-wrap:wrap;font-size:12px;color:var(--muted)}
.legend span{display:inline-flex;align-items:center;gap:6px}
.legend i{width:9px;height:9px;border-radius:3px;display:inline-block}
.bar-m{display:flex;align-items:center;gap:10px;margin:9px 0}
.bar-m .nm{width:110px;font-size:12.5px;color:var(--ink-2);flex-shrink:0}
.bar-m .tr{flex:1;height:16px;background:#f1f5f9;border-radius:5px;overflow:hidden}
.bar-m .tr i{display:block;height:100%;border-radius:5px}
.bar-m .vv{width:150px;text-align:right;font-size:12.5px;color:var(--ink-2);flex-shrink:0}

/* ===== 详情抽屉 ===== */
#mask{position:fixed;inset:0;background:rgba(15,23,42,.38);opacity:0;pointer-events:none;transition:.2s;z-index:40}
#mask.on{opacity:1;pointer-events:auto}
#drawer{position:fixed;top:0;right:-560px;width:560px;max-width:92vw;height:100%;background:#fff;z-index:50;transition:right .24s ease;display:flex;flex-direction:column;box-shadow:var(--shadow-lg)}
#drawer.on{right:0}
.dw-hd{padding:18px 22px;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:10px}
.dw-hd h3{font-size:16px;font-weight:700}
.dw-hd .x{margin-left:auto;width:32px;height:32px;border-radius:8px;display:flex;align-items:center;justify-content:center;color:var(--muted)}
.dw-hd .x:hover{background:var(--neutral-weak)}
.dw-bd{flex:1;overflow:auto;padding:20px 22px}
.dw-ft{padding:14px 22px;border-top:1px solid var(--line);display:flex;gap:10px}
.field-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px 20px}
.field{display:flex;flex-direction:column;gap:3px}
.field .k{font-size:12px;color:var(--muted)}
.field .v{font-size:14px;font-weight:550;word-break:break-all}
.section-title{font-size:12px;color:var(--muted);font-weight:700;letter-spacing:.04em;margin:22px 0 10px;display:flex;align-items:center;gap:8px}
.section-title::after{content:"";flex:1;height:1px;background:var(--line-2)}
.trace-list{display:flex;flex-direction:column}
.trace-item{display:flex;gap:12px;padding:10px 12px;border-radius:8px;background:#f8fafc;margin-bottom:6px}
.trace-item .t{width:88px;font-size:12px;color:var(--muted);flex-shrink:0}
.trace-item .c{font-size:13px;word-break:break-all}
.audit{position:relative;padding-left:20px}
.audit::before{content:"";position:absolute;left:6px;top:4px;bottom:4px;width:2px;background:var(--line)}
.audit .it{position:relative;padding:0 0 14px 4px}
.audit .it::before{content:"";position:absolute;left:-17px;top:5px;width:9px;height:9px;border-radius:50%;background:#fff;border:2px solid var(--brand)}
.audit .it.reject::before{border-color:#94a3b8}
.audit .it.green::before{border-color:var(--in)}
.audit .it .who{font-size:13px;font-weight:600}
.audit .it .act{font-size:12.5px;color:var(--ink-2);margin-top:1px}
.audit .it .tm{font-size:11.5px;color:var(--muted);margin-top:2px}

/* ===== 弹窗 ===== */
#modal-wrap{position:fixed;inset:0;display:none;align-items:center;justify-content:center;z-index:60;background:rgba(15,23,42,.42)}
#modal-wrap.on{display:flex}
#modal{width:440px;max-width:92vw;background:#fff;border-radius:14px;box-shadow:var(--shadow-lg);overflow:hidden;animation:pop .16s ease}
@keyframes pop{from{transform:scale(.96);opacity:0}to{transform:scale(1);opacity:1}}
.mo-hd{padding:18px 22px;display:flex;align-items:center;gap:10px}
.mo-hd .ic{width:36px;height:36px;border-radius:10px;display:flex;align-items:center;justify-content:center;flex-shrink:0}
.mo-hd .ic.warn{background:var(--warn-weak);color:var(--warn)}
.mo-hd .ic.ok{background:var(--ok-weak);color:var(--ok)}
.mo-hd .ic.danger{background:var(--danger-weak);color:var(--danger)}
.mo-hd h4{font-size:15.5px;font-weight:700}
.mo-hd p{font-size:12.5px;color:var(--muted);margin-top:2px}
.mo-bd{padding:6px 22px 4px;font-size:13.5px;color:var(--ink-2)}
.mo-bd .sum{background:#f8fafc;border:1px solid var(--line-2);border-radius:9px;padding:12px 14px;margin:10px 0;font-size:13px;line-height:1.7}
.mo-ft{padding:16px 22px;display:flex;gap:10px;justify-content:flex-end;border-top:1px solid var(--line-2)}
textarea.field{width:100%;min-height:76px;resize:vertical;border:1px solid var(--line);border-radius:8px;padding:10px 12px;font-family:inherit;font-size:13px;outline:none}
textarea.field:focus{border-color:var(--brand);box-shadow:0 0 0 3px #2563eb22}

/* toast */
#toast{position:fixed;top:18px;left:50%;transform:translateX(-50%) translateY(-80px);background:var(--ink);color:#fff;padding:10px 18px;border-radius:9px;font-size:13px;z-index:70;transition:.25s;display:flex;gap:8px;align-items:center;box-shadow:var(--shadow-lg);max-width:70vw}
#toast.on{transform:translateX(-50%) translateY(0)}
#toast.ok{background:var(--ok)}
#toast.err{background:var(--danger)}
#toast.info{background:var(--ink)}

.kpi-note{font-size:11.5px;color:var(--muted);text-align:right;margin-top:6px}
.empty{padding:40px;text-align:center;color:var(--muted)}
.small-print{font-size:11px;color:var(--muted);margin-top:14px;line-height:1.6}
.tag-mini{font-size:10.5px;background:var(--neutral-weak);color:var(--neutral);padding:1px 6px;border-radius:5px;margin-left:6px}

/* 加载态 */
.loading{text-align:center;padding:48px 0;color:var(--muted)}
.spinner{width:26px;height:26px;border:3px solid var(--line);border-top-color:var(--brand);border-radius:50%;margin:0 auto 10px;animation:spin .7s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}

@media(max-width:1080px){.stat-row{grid-template-columns:repeat(2,1fr)}.grid-2,.grid-2-1,.grid-3{grid-template-columns:1fr}}

/* ===== 通知铃铛下拉 ===== */
.notify-wrap{position:relative}
.notify-pop{position:absolute;right:0;top:44px;width:320px;background:#fff;border:1px solid var(--line-2);border-radius:12px;box-shadow:var(--shadow-lg);display:none;z-index:45;overflow:hidden}
.notify-pop.on{display:block}
.notify-head{padding:12px 16px;border-bottom:1px solid var(--line-2);font-weight:700;font-size:13.5px;display:flex;align-items:center;justify-content:space-between}
.notify-list{max-height:340px;overflow:auto}
.notify-item{display:flex;gap:10px;padding:12px 16px;border-bottom:1px solid var(--line-2);cursor:pointer}
.notify-item:last-child{border-bottom:none}
.notify-item:hover{background:#f8fafc}
.notify-item .ico{width:32px;height:32px;border-radius:8px;display:flex;align-items:center;justify-content:center;flex-shrink:0;font-size:15px}
.notify-item .ico.warn{background:var(--warn-weak);color:var(--warn)}
.notify-item .ico.danger{background:var(--danger-weak);color:var(--danger)}
.notify-item .ico.brand{background:var(--brand-weak);color:var(--brand)}
.notify-item .tx{flex:1;min-width:0}
.notify-item .tx .t{font-size:13px;font-weight:600;color:var(--ink)}
.notify-item .tx .d{font-size:12px;color:var(--muted);margin-top:2px}
.notify-empty{padding:28px;text-align:center;color:var(--muted);font-size:13px}

// API 客户端：统一封装 fetch + JWT 鉴权 + 401 处理
const TOKEN_KEY = "wf_token";

export const auth = {
  get token() { return localStorage.getItem(TOKEN_KEY) || ""; },
  set(token) { localStorage.setItem(TOKEN_KEY, token); },
  clear() { localStorage.removeItem(TOKEN_KEY); },
};

function buildHeaders(headers = {}) {
  return { "Content-Type": "application/json", Authorization: `Bearer ${auth.token}`, ...headers };
}

async function handle(res) {
  if (res.status === 401) {
    auth.clear();
    if (window.__onUnauth) window.__onUnauth();
    throw new Error("登录已过期，请重新登录");
  }
  let data = null;
  try { data = await res.json(); } catch { /* noop */ }
  if (!res.ok) {
    const msg = (data && (data.detail || data.message)) || `请求失败（${res.status}）`;
    throw new Error(typeof msg === "string" ? msg : JSON.stringify(msg));
  }
  return data;
}

async function get(path) {
  const res = await fetch(path, { headers: buildHeaders() });
  return handle(res);
}

async function post(path, body) {
  const res = await fetch(path, { method: "POST", headers: buildHeaders(), body: JSON.stringify(body || {}) });
  return handle(res);
}

// multipart 上传（文件导入）
async function upload(path, formData) {
  const res = await fetch(path, {
    method: "POST",
    headers: { Authorization: `Bearer ${auth.token}` },
    body: formData,
  });
  return handle(res);
}

export const api = {
  // 认证
  login: (username, password) =>
    fetch("/api/auth/login", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ username, password }) }).then(handle),

  // 复核
  summary: () => get("/api/dashboard/summary"),
  pending: () => get("/api/review/pending?limit=500"),
  decide: (record_id, result, matched_subject, comment) =>
    post("/api/review/decide", { record_id, result, matched_subject, comment }),
  decideBatch: (record_ids, result, comment) =>
    post("/api/review/decide-batch", { record_ids, result, comment }),

  // 推送
  pushRecord: (record_id) => post("/api/push/record", { record_id }),
  pushBatch: (batch_id) => post("/api/push/batch", { batch_id }),

  // 溯源
  traceByRecord: (record_id) => get(`/api/trace/by-record?record_id=${record_id}`),
  traceByVoucher: (voucher_no) => get(`/api/trace/by-voucher?voucher_no=${encodeURIComponent(voucher_no)}`),

  // 看板
  overview: () => get("/api/dashboard/overview"),
  bankDistribution: () => get("/api/dashboard/bank-distribution"),
  exceptions: () => get("/api/dashboard/exceptions?limit=500"),
  recon: () => get("/api/dashboard/recon"),

  // 采集（演示入口）
  ingestMock: (bank_code, account_no, count) => {
    const qs = `bank_code=${encodeURIComponent(bank_code)}&account_no=${encodeURIComponent(account_no)}&count=${count}`;
    return post(`/api/ingest/mock?${qs}`);
  },
  ingestFile: (file, bank_code, account_no) => {
    const fd = new FormData();
    fd.append("file", file);
    fd.append("bank_code", bank_code);
    fd.append("account_no", account_no);
    return upload("/api/ingest/file", fd);
  },
};

// 四看板：流水总览 / 银行分布 / 异常预警 / 对账钩稽
import { api } from "./api.js";
import * as ui from "./ui.js";
import { openRecordDrawer } from "./trace.js";

const PALETTE = ["#2563eb", "#0e7490", "#6366f1", "#16a34a", "#d97706", "#dc2626", "#14b8a6", "#94a3b8"];
const RULE_META = {
  R001: ["重复流水", "高", "#dc2626"],
  R002: ["负金额/方向非法", "高", "#dc2626"],
  R003: ["缺字段", "中", "#f59e0b"],
  R004: ["超阈值", "中", "#f97316"],
  R005: ["币种异常", "中", "#f59e0b"],
};
const DASH_TITLE = { overview: "流水总览", bank: "银行分布", alert: "异常预警", recon: "对账钩稽" };

function wrapCard(title, inner, sub = "") {
  return `<div class="card">
    <div class="card-hd"><h3>${ui.esc(title)}</h3>${sub ? `<span class="sub">${sub}</span>` : ""}</div>
    <div class="card-bd">${inner}</div>
  </div>`;
}

function statCard(lbl, valHtml, deltaHtml, cls = "") {
  return `<div class="stat ${cls}"><div class="lbl">${lbl}</div><div class="val num">${valHtml}</div><div class="delta">${deltaHtml}</div>${cls ? `<div class="strip"></div>` : ""}</div>`;
}

// ---------- SVG 图表 ----------
function lineChart(series, labels, opts = {}) {
  const w = opts.w || 620, h = opts.h || 240, p = 34;
  const max = Math.max(1, ...series.flatMap((s) => s.values));
  const n = Math.max(labels.length, 1);
  const px = (i) => p + i * (w - 2 * p) / Math.max(1, n - 1);
  const py = (v) => h - p - (v / max) * (h - 2 * p);
  let grid = "";
  for (const g of [0, 0.25, 0.5, 0.75, 1]) {
    const y = py(max * g);
    grid += `<line x1="${p}" y1="${y}" x2="${w - p}" y2="${y}" stroke="#eef2f7"/>`;
    grid += `<text x="${p - 8}" y="${y + 3}" font-size="10" fill="#94a3b8" text-anchor="end">${Math.round(max * g).toLocaleString()}</text>`;
  }
  let paths = "";
  series.forEach((s) => {
    const pts = s.values.map((v, i) => `${i ? "L" : "M"}${px(i).toFixed(1)} ${py(v).toFixed(1)}`).join(" ");
    const area = `M${px(0).toFixed(1)} ${h - p} ${pts} L${px(s.values.length - 1).toFixed(1)} ${h - p} Z`;
    paths += `<path d="${area}" fill="${s.color}18"/>`;
    paths += `<path d="${pts}" stroke="${s.color}" stroke-width="2.2" fill="none"/>`;
  });
  let lbls = "";
  if (n > 1) labels.forEach((lb, i) => { lbls += `<text x="${px(i)}" y="${h - 10}" font-size="10" fill="#94a3b8" text-anchor="middle">${ui.esc(lb)}</text>`; });
  return `<svg viewBox="0 0 ${w} ${h}" class="chart">${grid}${paths}${lbls}</svg>`;
}

function donut(items) {
  const size = 200, stroke = 30, r = (size - stroke) / 2, c = size / 2;
  const total = items.reduce((a, b) => a + b.value, 0) || 1;
  const circ = 2 * Math.PI * r;
  let off = 0, segs = "";
  items.forEach((it) => {
    const len = it.value / total * circ;
    segs += `<circle cx="${c}" cy="${c}" r="${r}" fill="none" stroke="${it.color}" stroke-width="${stroke}" stroke-dasharray="${len} ${circ - len}" stroke-dashoffset="${-off}" transform="rotate(-90 ${c} ${c})"><title>${ui.esc(it.name)}: ${ui.fmtAmount(it.value)}</title></circle>`;
    off += len;
  });
  const center = total >= 10000 ? (total / 10000).toFixed(1) + "万" : ui.fmtInt(total);
  const legend = items.map((it) => `
    <div style="display:flex;justify-content:space-between;align-items:center;padding:9px 0;border-bottom:1px solid var(--line-2)">
      <span class="legend"><i style="background:${it.color}"></i>${ui.esc(it.name)}</span>
      <b class="mono">${(it.value / total * 100).toFixed(1)}%</b>
    </div>`).join("");
  return `<div style="display:flex;align-items:center;gap:26px;flex-wrap:wrap">
    <svg width="${size}" height="${size}" viewBox="0 0 ${size} ${size}">${segs}
      <text x="${c}" y="${c - 4}" text-anchor="middle" font-size="20" font-weight="700" fill="#0f172a">${center}</text>
      <text x="${c}" y="${c + 16}" text-anchor="middle" font-size="11" fill="#64748b">总流水(元)</text>
    </svg>
    <div style="flex:1;min-width:160px">${legend}</div>
  </div>`;
}

function hBars(items, opts = {}) {
  const max = opts.max || Math.max(1, ...items.map((i) => i.value));
  return items.map((it) => `
    <div class="bar-m">
      <div class="nm">${it.label}</div>
      <div class="tr"><i style="width:${Math.max(2, (it.value / max * 100).toFixed(1))}%;background:${it.color}"></i></div>
      <div class="vv mono">${it.valueText || ui.fmtAmount(it.value)}</div>
    </div>`).join("");
}

// ---------- 壳：tab + 面板 ----------
export async function renderDash(root, tab = "overview") {
  const tabs = ["overview", "bank", "alert", "recon"];
  root.innerHTML = `
    <div class="tabs" id="dash-tabs">${tabs.map((t) => `<button class="${t === tab ? "active" : ""}" data-tab="${t}">${DASH_TITLE[t]}</button>`).join("")}</div>
    <div class="dash on" id="dash-panel"></div>`;
  const panel = () => root.querySelector("#dash-panel");

  async function load(t) {
    root.querySelectorAll("#dash-tabs button").forEach((b) => b.classList.toggle("active", b.dataset.tab === t));
    document.getElementById("crumb").textContent = "可视化看板 · " + DASH_TITLE[t];
    const el = panel();
    el.innerHTML = ui.loadingHtml();
    const renderers = { overview: renderOverview, bank: renderBank, alert: renderAlert, recon: renderRecon };
    await renderers[t](el);
  }

  root.querySelectorAll("#dash-tabs button").forEach((b) => {
    b.addEventListener("click", () => load(b.dataset.tab));
  });

  await load(tab in { overview: 1, bank: 1, alert: 1, recon: 1 } ? tab : "overview");
}

// ---------- 1. 流水总览 ----------
async function renderOverview(root) {
  const rows = await api.overview();
  if (!rows.length) { root.innerHTML = ui.emptyHtml("暂无流水数据，可先在复核工作台 Mock 采集"); return; }

  let credit = 0, debit = 0, totalCnt = 0;
  const dateMap = new Map();
  const acctMap = new Map();
  rows.forEach((r) => {
    const amt = Number(r.amount), cnt = r.cnt;
    if (r.dc_flag === "C") credit += amt; else debit += amt;
    totalCnt += cnt;
    const d = dateMap.get(r.txn_date) || { c: 0, d: 0 };
    if (r.dc_flag === "C") d.c += amt; else d.d += amt;
    dateMap.set(r.txn_date, d);
    const a = acctMap.get(r.account_name) || { bank: r.bank_name, c: 0, d: 0, cnt: 0 };
    if (r.dc_flag === "C") a.c += amt; else a.d += amt;
    a.cnt += cnt;
    acctMap.set(r.account_name, a);
  });
  const net = credit - debit;

  const kpis = `
    ${statCard("本期收入", `<span style="color:var(--in)">${ui.fmtAmount(credit)}</span>`, "本期累计收入", "gain")}
    ${statCard("本期支出", `<span style="color:var(--out)">${ui.fmtAmount(debit)}</span>`, "本期累计支出", "pay")}
    ${statCard("净流入", `<span style="color:${net >= 0 ? "var(--in)" : "var(--out)"}">${(net >= 0 ? "+" : "−") + ui.fmtAmount(Math.abs(net))}</span>`, "净额 = 收 − 支", "net")}
    ${statCard("流水总笔数", `${ui.fmtInt(totalCnt)}<small> 笔</small>`, "覆盖 ≥80% 流水", "cnt")}`;

  const dateKeys = Array.from(dateMap.keys()).sort();
  const labels = dateKeys.map((d) => d.slice(5));
  const series = [
    { name: "收入", color: "#059669", values: dateKeys.map((d) => dateMap.get(d).c) },
    { name: "支出", color: "#dc2626", values: dateKeys.map((d) => dateMap.get(d).d) },
  ];

  const acctItems = Array.from(acctMap.entries()).map(([label, v], i) => ({ label, value: v.c + v.d, color: PALETTE[i % PALETTE.length] }));
  const acctMax = Math.max(1, ...acctItems.map((i) => i.value));

  const acctRows = Array.from(acctMap.entries()).sort((a, b) => (b[1].c + b[1].d) - (a[1].c + a[1].d)).map(([label, v]) => `
    <tr>
      <td>${ui.esc(label)}</td><td>${ui.esc(v.bank)}</td>
      <td class="amt in">${ui.money(v.c)}</td><td class="amt out">${ui.money(v.d)}</td>
      <td class="num">${ui.fmtInt(v.cnt)}</td>
      <td class="amt ${v.c - v.d >= 0 ? "in" : "out"}">${v.c - v.d >= 0 ? "+" : "−"}${ui.money(Math.abs(v.c - v.d))}</td>
    </tr>`).join("");

  root.innerHTML = `
    <div class="section-gap">
      <div class="stat-row">${kpis}</div>
      <div class="grid-2-1">
        ${wrapCard("收支趋势", lineChart(series, labels) + `<div class="legend" style="margin-top:10px"><span><i style="background:#059669"></i>收入（收）</span><span><i style="background:#dc2626"></i>支出（付）</span></div>`, "按日聚合")}
        ${wrapCard("账户收支构成", hBars(acctItems, { max: acctMax }), "金额 Top 5")}
      </div>
      ${wrapCard("账户流水明细", `
        <div class="tbl-wrap"><table class="tbl">
          <thead><tr><th>账户</th><th>银行</th><th>收入(元)</th><th>支出(元)</th><th>笔数</th><th>净额(元)</th></tr></thead>
          <tbody>${acctRows}</tbody>
        </table></div>`, "本期聚合")}
    </div>`;
}

// ---------- 2. 银行分布 ----------
async function renderBank(root) {
  const rows = await api.bankDistribution();
  if (!rows.length) { root.innerHTML = ui.emptyHtml("暂无流水数据"); return; }

  const byBank = new Map();
  rows.forEach((r) => {
    const amt = Number(r.credit_amount) + Number(r.debit_amount);
    byBank.set(r.bank_name, (byBank.get(r.bank_name) || 0) + amt);
  });
  const bankItems = Array.from(byBank.entries()).map(([name, value], i) => ({ name, value, color: PALETTE[i % PALETTE.length] }));
  const total = bankItems.reduce((a, b) => a + b.value, 0) || 1;

  const acctItems = rows.map((r, i) => ({ label: `${r.bank_name} · ${r.account_name}`, value: Number(r.credit_amount) + Number(r.debit_amount), color: PALETTE[i % PALETTE.length] }));
  const acctMax = Math.max(1, ...acctItems.map((i) => i.value));

  const detailRows = rows.map((r) => {
    const amount = Number(r.credit_amount) + Number(r.debit_amount);
    return `<tr>
      <td>${ui.esc(r.bank_name)}</td><td>${ui.esc(r.account_name)}</td>
      <td class="num">${ui.money(amount)}</td>
      <td class="num">${(amount / total * 100).toFixed(1)}%</td>
      <td class="num">${ui.fmtInt(r.cnt)}</td>
    </tr>`;
  }).join("");

  root.innerHTML = `
    <div class="section-gap">
      <div class="grid-2-1">
        ${wrapCard("银行流水占比", donut(bankItems), "按金额")}
        ${wrapCard("账户占比", hBars(acctItems, { max: acctMax }), "按金额 · 收付加权")}
      </div>
      ${wrapCard("银行 / 账户分布明细", `
        <div class="tbl-wrap"><table class="tbl">
          <thead><tr><th>银行</th><th>账户</th><th>流水金额(元)</th><th>占比</th><th>笔数</th></tr></thead>
          <tbody>${detailRows}
            <tr style="background:#f8fafc"><td colspan="2"><b>合计</b></td><td class="num"><b>${ui.money(total)}</b></td><td><b>100%</b></td><td class="num"><b>${ui.fmtInt(rows.reduce((s, r) => s + r.cnt, 0))}</b></td></tr>
          </tbody>
        </table></div>`)}
    </div>`;
}

// ---------- 3. 异常预警 ----------
async function renderAlert(root) {
  const rows = await api.exceptions();
  if (!rows.length) { root.innerHTML = ui.emptyHtml("暂无异常/预警流水"); return; }

  const failCount = rows.filter((r) => r.rule_result === "FAIL").length;
  const warnCount = rows.length - failCount;
  const ruleSet = new Set(rows.map((r) => r.rule_code));

  const byRule = new Map();
  rows.forEach((r) => byRule.set(r.rule_code, (byRule.get(r.rule_code) || 0) + 1));
  const bars = Array.from(byRule.entries()).map(([code, value]) => {
    const [label, sev, color] = RULE_META[code] || [code, ruleSev(code, value), "#94a3b8"];
    return { label: `${label}<span class="tag-mini">${sev}</span>`, value, color, valueText: `${value} 笔` };
  });
  const barMax = Math.max(1, ...bars.map((b) => b.value));

  const listRows = rows.map((r) => {
    const [label, sev] = RULE_META[r.rule_code] || [r.rule_code, ruleSev(r.rule_code)];
    const sevCls = sev === "高" ? "b-err" : "b-low";
    const amt = r.dc_flag === "C" ? `<span class="amt in">+¥ ${ui.money(r.amount)}</span>` : `<span class="amt out">−¥ ${ui.money(r.amount)}</span>`;
    return `<tr data-id="${r.record_id}">
      <td><span class="badge ${sevCls}">${sev}</span></td>
      <td>${ui.esc(label)}</td>
      <td class="mono">${ui.esc(r.txn_no)}</td>
      <td class="num">${amt}</td>
      <td>${ui.esc(r.counterparty_name || "—")}</td>
      <td style="max-width:260px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${ui.esc(r.error_detail || "")}">${ui.esc(r.error_detail || "—")}</td>
      <td><button class="link-btn row-open" data-id="${r.record_id}">去复核</button></td>
    </tr>`;
  }).join("");

  const b = document.getElementById("nav-badge-alert");
  if (b) b.textContent = rows.length > 0 ? ui.fmtInt(rows.length) : "";

  root.innerHTML = `
    <div class="section-gap">
      <div class="stat-row">
        ${statCard("异常合计", `<span style="color:var(--danger)">${ui.fmtInt(rows.length)}</span>`, "需人工处理")}
        ${statCard("校验失败(FAIL)", `<span style="color:var(--danger)">${ui.fmtInt(failCount)}</span>`, "重复/负额/缺字段/币种")}
        ${statCard("需人工复核(WARN)", `<span style="color:var(--warn)">${ui.fmtInt(warnCount)}</span>`, "超阈值转人工")}
        ${statCard("覆盖规则类型", `<span style="color:var(--info)">${ui.fmtInt(ruleSet.size)}</span>`, "R002–R005")}
      </div>
      <div class="grid-2">
        ${wrapCard("异常类型分布", hBars(bars, { max: barMax }), "采集校验结果 · 按严重度")}
        ${wrapCard("规则说明", `<div class="muted" style="line-height:2;font-size:13px">
          <div>· <b>重复流水 / 负金额 / 缺字段 / 币种非法</b>：自动驳回待处理（FAIL）。</div>
          <div>· <b>单笔金额超阈值</b>：转人工复核（WARN）。</div>
          <div>· 点击清单任意行可进入复核详情。</div>
        </div>`)}
      </div>
      ${wrapCard("异常流水清单", `
        <div class="tbl-wrap"><table class="tbl">
          <thead><tr><th>严重度</th><th>类型</th><th>流水号</th><th>金额</th><th>对方户名</th><th>问题描述</th><th style="width:88px">操作</th></tr></thead>
          <tbody>${listRows}</tbody>
        </table></div>`, "点击「去复核」跳转复核详情")}
    </div>`;

  root.querySelectorAll("tr[data-id]").forEach((tr) => {
    tr.addEventListener("click", (e) => {
      if (e.target.closest(".row-open")) return;
      openRecordDrawer(Number(tr.dataset.id));
    });
  });
  root.querySelectorAll(".row-open").forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.stopPropagation();
      openRecordDrawer(Number(btn.dataset.id));
    });
  });
}

function ruleSev(code, result) {
  if (result === "WARN") return "中";
  if (result === "FAIL") return "高";
  return "中";
}

// ---------- 4. 对账钩稽 ----------
async function renderRecon(root) {
  const rows = await api.recon();
  const diffRows = rows.filter((r) => r.count_diff !== 0);
  const diffAmount = rows.reduce((s, r) => s + (Number(r.expected_amount) - Number(r.loaded_amount)), 0);

  const tableRows = rows.map((r) => {
    const hasDiff = r.count_diff !== 0;
    const aDiff = Number(r.expected_amount) - Number(r.loaded_amount);
    return `<tr>
      <td class="mono">${ui.esc(r.batch_no)}</td>
      <td>${ui.esc(r.source_type)}</td>
      <td class="num">${ui.fmtInt(r.loaded_count)}</td>
      <td class="num">${ui.money(r.loaded_amount)}</td>
      <td class="num">${ui.fmtInt(r.expected_count)}</td>
      <td class="num">${ui.money(r.expected_amount)}</td>
      <td class="num" style="color:${hasDiff ? "var(--danger)" : "inherit"}">${hasDiff ? "−" + ui.fmtInt(Math.abs(r.count_diff)) : "0"}</td>
      <td class="num" style="color:${aDiff !== 0 ? "var(--danger)" : "inherit"}">${aDiff !== 0 ? (aDiff < 0 ? "+" : "−") + ui.money(Math.abs(aDiff)) : "¥0"}</td>
      <td>${hasDiff ? '<span class="badge b-err">差异</span>' : '<span class="badge b-pass">一致</span>'}</td>
      <td>${!hasDiff && r.loaded_count > 0 ? `<button class="link-btn" data-push="${r.batch_id}">推送批次</button>` : ""}</td>
    </tr>`;
  }).join("");

  const diffDetail = diffRows.length ? diffRows.map((r) => `
    <div class="trace-item"><span class="t">批次</span><span class="c mono">${ui.esc(r.batch_no)}（${ui.esc(r.source_type)}）</span></div>
    <div class="trace-item"><span class="t">笔数差</span><span class="c" style="color:var(--danger)">−${ui.fmtInt(Math.abs(r.count_diff))} 笔（导入 ${ui.fmtInt(r.loaded_count)} / 预期 ${ui.fmtInt(r.expected_count)}）</span></div>
    <div class="trace-item"><span class="t">金额差</span><span class="c" style="color:var(--danger)">${Number(r.expected_amount) - Number(r.loaded_amount) < 0 ? "+" : "−"}${ui.money(Math.abs(Number(r.expected_amount) - Number(r.loaded_amount)))}</span></div>
    <div class="trace-item"><span class="t">建议</span><span class="c">核对源文件 → 重新导入 → 再次勾稽</span></div>`).join('<div style="height:6px"></div>') : `<div class="muted" style="font-size:13px">当前无差异批次</div>`;

  root.innerHTML = `
    <div class="section-gap">
      <div class="stat-row">
        ${statCard("批次总数", `<span style="color:var(--brand)">${ui.fmtInt(rows.length)}</span>`, "近 7 天")}
        ${statCard("对账一致", `<span style="color:var(--ok)">${ui.fmtInt(rows.length - diffRows.length)}</span>`, "笔数 + 金额全平")}
        ${statCard("存在差异", `<span style="color:var(--warn)">${ui.fmtInt(diffRows.length)}</span>`, "需核对")}
        ${statCard("差异金额", `<span style="color:var(--danger)">${diffAmount < 0 ? "+" : "−"}${ui.money(Math.abs(diffAmount))}</span>`, "差额待追平")}
      </div>
      ${wrapCard("批次对账状态", `
        <div class="tbl-wrap"><table class="tbl">
          <thead><tr><th>批次号</th><th>来源</th><th>导入笔数</th><th>导入金额(元)</th><th>预期笔数</th><th>预期金额(元)</th><th>笔差</th><th>额差</th><th>状态</th><th></th></tr></thead>
          <tbody>${tableRows || `<tr><td colspan="10"><div class="muted" style="padding:20px">暂无批次</div></td></tr>`}</tbody>
        </table></div>
        <div class="small-print">※ 勾稽规则：导入笔数 / 金额须与「预期值」完全一致；不一致批次会被置顶并阻断批量推送。</div>`, "导入 vs 预期 · 笔数/金额勾稽")}
      <div class="grid-2">
        ${wrapCard("差异批次 · 明细跟踪", diffDetail)}
        ${wrapCard("凭证 ↔ 流水 双向钩稽", `
          <div style="display:flex;gap:12px;flex-wrap:wrap;align-items:flex-end">
            <div style="flex:1;min-width:200px"><span class="hint">按金蝶凭证号回溯（账 → 单）</span><input class="input" id="recon-voucher" placeholder="如 KV2026-..." style="width:100%;margin-top:4px"/></div>
            <button class="btn btn-pri btn-sm" id="recon-byvoucher">凭证回溯</button>
            <div style="flex:1;min-width:140px"><span class="hint">按记录号回溯（单 → 账）</span><input class="input" id="recon-record" placeholder="record_id" style="width:100%;margin-top:4px"/></div>
            <button class="btn btn-ghost btn-sm" id="recon-byrecord">流水回溯</button>
          </div>
          <div style="margin-top:14px">
            <div class="trace-item"><span class="t">正向追溯</span><span class="c" style="color:var(--ok)">凭证 → 流水 ✓ 可回查</span></div>
            <div class="trace-item"><span class="t">反向追溯</span><span class="c" style="color:var(--ok)">流水 → 凭证 ✓ 可回查</span></div>
          </div>`, "溯源一致性检查")}
      </div>
    </div>`;

  root.querySelectorAll("[data-push]").forEach((btn) => {
    btn.addEventListener("click", async (e) => {
      e.stopPropagation();
      const batchId = Number(btn.dataset.push);
      ui.confirmModal({
        title: "推送整批到金蝶",
        danger: true,
        okText: "确认推送",
        html: `<p>将批次 <b>#${batchId}</b> 中所有「已通过复核」的流水推送至金蝶并自动制证。</p>
               <p class="muted" style="font-size:12px;margin-top:6px">不可逆操作，请二次确认。</p>`,
        onOk: async () => {
          const r = await api.pushBatch(batchId);
          ui.toast(`已推送 ${r.pushed} 笔`, "success");
          renderRecon(root);
        },
      });
    });
  });

  document.getElementById("recon-byvoucher").addEventListener("click", async () => {
    const v = document.getElementById("recon-voucher").value.trim();
    if (!v) { ui.toast("请输入凭证号", "error"); return; }
    try {
      const tr = await api.traceByVoucher(v);
      openRecordDrawer(tr.flow.record_id);
    } catch (e) { ui.toast(e.message, "error"); }
  });
  document.getElementById("recon-byrecord").addEventListener("click", () => {
    const v = document.getElementById("recon-record").value.trim();
    if (!v) { ui.toast("请输入记录号", "error"); return; }
    openRecordDrawer(Number(v));
  });
}

// 入口：登录门、会话恢复、导航路由、顶栏时钟、侧栏用户信息
import { api, auth } from "./api.js";
import * as ui from "./ui.js";
import { renderReview } from "./review.js";
import { renderDash } from "./dashboards.js";

const CRUMB = {
  review: ["复核工作台", "待复核队列 · 规则内自动通过，低置信/异常转人工"],
  overview: ["可视化看板 · 流水总览", "MVP 四看板 · 自研轻量定制 · 取数可信"],
  bank: ["可视化看板 · 银行分布", "MVP 四看板 · 自研轻量定制 · 取数可信"],
  alert: ["可视化看板 · 异常预警", "MVP 四看板 · 自研轻量定制 · 取数可信"],
  recon: ["可视化看板 · 对账钩稽", "MVP 四看板 · 自研轻量定制 · 取数可信"],
};

let currentView = "review";
let currentTab = "overview";

function navigate(view, tab = "overview") {
  currentView = view;
  currentTab = tab;
  document.querySelectorAll(".nav-item[data-view]").forEach((n) => {
    const active = view === "dash"
      ? n.dataset.view === "dash" && n.dataset.tab === tab
      : n.dataset.view === view;
    n.classList.toggle("active", active);
  });
  const c = CRUMB[view === "dash" ? tab : view] || CRUMB.review;
  document.getElementById("crumb").textContent = c[0];
  document.getElementById("crumb-sub").textContent = c[1];
  const el = document.getElementById("view");
  el.innerHTML = ui.loadingHtml();
  if (view === "dash") renderDash(el, tab);
  else renderReview(el);
}

function showApp(user) {
  document.getElementById("login").style.display = "none";
  document.getElementById("app").classList.add("on");
  document.getElementById("side-name").textContent = `${user.display_name || user.username} · ${user.role === "ADMIN" ? "管理员" : "复核员"}`;
  document.getElementById("side-avatar").textContent = (user.display_name || user.username).charAt(0);
  navigate("review");
}

window.__onUnauth = () => {
  document.getElementById("app").classList.remove("on");
  document.getElementById("login").style.display = "flex";
  ui.toast("会话已过期，请重新登录", "error");
};

function initLogin() {
  const btn = document.getElementById("lg-btn");
  const errEl = document.getElementById("lg-error");
  const submit = async () => {
    errEl.textContent = "";
    btn.disabled = true;
    btn.textContent = "登录中…";
    try {
      const data = await api.login(
        document.getElementById("lg-user").value.trim(),
        document.getElementById("lg-pass").value,
      );
      auth.set(data.access_token);
      showApp(data);
    } catch (err) {
      errEl.textContent = err.message || "登录失败";
    } finally {
      btn.disabled = false;
      btn.textContent = "登 录";
    }
  };
  btn.addEventListener("click", submit);
  document.addEventListener("keydown", (e) => {
    if (e.key === "Enter" && document.getElementById("login").style.display !== "none") submit();
  });
}

function initNav() {
  document.querySelectorAll(".nav-item[data-view]").forEach((n) => {
    n.addEventListener("click", () => navigate(n.dataset.view, n.dataset.tab || "overview"));
  });
  document.getElementById("logout-btn").addEventListener("click", () => {
    auth.clear();
    document.getElementById("app").classList.remove("on");
    document.getElementById("login").style.display = "flex";
    ui.toast("已退出登录", "info");
  });
}

function startClock() {
  const el = document.getElementById("clock");
  const tick = () => {
    const d = new Date();
    const pad = (x) => String(x).padStart(2, "0");
    el.textContent = `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
  };
  tick();
  setInterval(tick, 1000);
}

function initNotify() {
  const btn = document.getElementById("notify-btn");
  const pop = document.getElementById("notify-pop");
  const dot = document.getElementById("notify-dot");
  if (!btn || !pop || !dot) return;

  function itemHtml(icon, glyph, title, desc, view, tab) {
    return `<div class="notify-item" data-view="${view}" data-tab="${tab || ""}">
      <div class="ico ${icon}">${glyph}</div>
      <div class="tx"><div class="t">${ui.esc(title)}</div><div class="d">${ui.esc(desc)}</div></div>
    </div>`;
  }

  async function refreshDot() {
    try {
      const s = await api.summary();
      dot.style.display = (s.pending_review || 0) > 0 ? "block" : "none";
    } catch { /* 红点刷新失败可忽略 */ }
  }

  async function open() {
    pop.innerHTML = ui.loadingHtml();
    pop.classList.add("on");
    try {
      const [s, ex] = await Promise.all([api.summary(), api.exceptions()]);
      const pending = s.pending_review || 0;
      const exCount = Array.isArray(ex) ? ex.length : 0;
      dot.style.display = pending > 0 ? "block" : "none";
      const items = [
        itemHtml("warn", "⚠", `待复核 ${pending} 笔流水`, pending > 0 ? "金额超阈值或校验告警，需人工复核" : "当前无待复核流水", "review", ""),
        itemHtml(exCount > 0 ? "danger" : "brand", exCount > 0 ? "!" : "✓", `异常预警 ${exCount} 笔`, exCount > 0 ? "存在校验失败/告警，前往异常看板关注" : "当前无异常预警", "dash", "alert"),
        itemHtml("brand", "→", `今日已推送 ${s.today_pushed || 0} 笔`, `自动通过率 ${((s.auto_pass_rate || 0) * 100).toFixed(1)}%`, "review", ""),
      ];
      pop.innerHTML = `<div class="notify-head">通知<span class="hint">待复核 ${pending}</span></div>
        <div class="notify-list">${items.join("")}</div>`;
      pop.querySelectorAll(".notify-item").forEach((node) => {
        node.addEventListener("click", () => {
          pop.classList.remove("on");
          const v = node.dataset.view;
          navigate(v === "dash" ? "dash" : "review", node.dataset.tab || "overview");
        });
      });
    } catch (e) {
      pop.innerHTML = `<div class="notify-empty">加载失败：${ui.esc(e.message || e)}</div>`;
    }
  }

  btn.addEventListener("click", (e) => {
    e.stopPropagation();
    if (pop.classList.contains("on")) { pop.classList.remove("on"); return; }
    open();
  });
  document.addEventListener("click", (e) => {
    if (pop.classList.contains("on") && !pop.contains(e.target) && e.target !== btn && !btn.contains(e.target)) {
      pop.classList.remove("on");
    }
  });
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") pop.classList.remove("on");
  });

  if (auth.token) refreshDot();
}

initLogin();
initNav();
initNotify();
startClock();

// 刷新页面：已有 token 则直接进入工作台（首页渲染若 401 会自动回退）
if (auth.token) {
  document.getElementById("login").style.display = "none";
  document.getElementById("app").classList.add("on");
  document.getElementById("side-name").textContent = "财务账号";
  document.getElementById("side-avatar").textContent = "财";
  navigate("review");
}

// 复核工作台：统计卡 + 待复核队列（11 列）+ 筛选 + 批量操作 + Mock/文件采集入口
import { api } from "./api.js";
import * as ui from "./ui.js";
import { openRecordDrawer } from "./trace.js";

let pendingData = [];
let selected = new Set();

function dirHtml(dc) {
  return dc === "C" ? '<span class="dir-tag in">收 ▲</span>' : '<span class="dir-tag out">支 ▼</span>';
}

function amtHtml(dc, amt) {
  const c = dc === "C" ? "in" : "out";
  const sgn = dc === "C" ? "+" : "−";
  return `<span class="amt ${c}">${sgn}¥ ${ui.money(amt)}</span>`;
}

export async function renderReview(root) {
  root.innerHTML = `
    <div class="section-gap">
      <div class="stat-row">
        <div class="stat"><div class="lbl">待复核</div><div class="val num" style="color:var(--warn)" id="stat-0">—</div><div class="delta" id="stat-d-0"></div></div>
        <div class="stat"><div class="lbl">今日已复核</div><div class="val num" style="color:var(--ok)" id="stat-1">—</div><div class="delta" id="stat-d-1"></div></div>
        <div class="stat"><div class="lbl">今日已推送金蝶</div><div class="val num" style="color:var(--brand)" id="stat-2">—</div><div class="delta" id="stat-d-2"></div></div>
        <div class="stat"><div class="lbl">自动通过率</div><div class="val num" id="stat-3">—</div><div class="delta" id="stat-d-3"></div></div>
      </div>

      <div class="card">
        <div class="card-hd">
          <h3>流水复核队列</h3><span class="sub">点击行查看详情；支持批量操作</span>
          <div class="right">
            <button class="btn btn-ghost btn-sm" id="btn-refresh">↻ 刷新</button>
            <button class="btn btn-pri btn-sm" id="btn-push">推送金蝶</button>
          </div>
        </div>
        <div class="card-bd">
          <div class="filterbar">
            <div class="search">🔍<input id="f-search" placeholder="流水号 / 对方户名 / 摘要" /></div>
            <select class="select" id="f-status">
              <option value="">全部状态</option>
              <option value="REVIEW_READY">待复核</option>
              <option value="REVIEW_PASSED">自动通过</option>
              <option value="KINGDEE_POSTED">已推送</option>
              <option value="REJECTED">已驳回</option>
            </select>
            <select class="select" id="f-bank"><option value="">全部银行</option></select>
            <select class="select" id="f-acct"><option value="">全部账户</option></select>
            <input type="date" class="input" id="f-date" />
            <div class="right">
              <label class="ck"><input type="checkbox" id="chk-all" /> 全选</label>
              <button class="btn btn-ghost btn-sm" id="btn-batch-reject" disabled>批量驳回</button>
              <button class="btn btn-ok btn-sm" id="btn-batch-pass" disabled>批量通过</button>
            </div>
          </div>
          <div class="tbl-wrap" style="max-height:62vh">
            <table class="tbl">
              <thead><tr>
                <th style="width:38px"></th><th>流水号</th><th>日期</th><th>借贷</th><th>金额</th>
                <th>对方户名</th><th>账户</th><th>摘要</th><th>校验</th><th>复核状态</th><th style="width:88px">操作</th>
              </tr></thead>
              <tbody id="review-tbody"><tr><td colspan="11">${ui.loadingHtml()}</td></tr></tbody>
            </table>
          </div>
        </div>
      </div>
    </div>`;

  bindEvents();
  await Promise.all([loadSummary(), loadPending()]);
}

function bindEvents() {
  document.getElementById("chk-all").addEventListener("change", (e) => {
    selected = new Set();
    if (e.target.checked) filteredRows().forEach((r) => selected.add(r.record_id));
    renderRows();
    refreshBatchState();
  });
  document.getElementById("f-search").addEventListener("input", renderRows);
  document.getElementById("f-date").addEventListener("change", renderRows);
  document.getElementById("f-status").addEventListener("change", renderRows);
  document.getElementById("f-bank").addEventListener("change", renderRows);
  document.getElementById("f-acct").addEventListener("change", renderRows);
  document.getElementById("btn-refresh").addEventListener("click", async () => {
    await Promise.all([loadSummary(), loadPending()]);
    ui.toast("已刷新队列", "info");
  });
  document.getElementById("btn-push").addEventListener("click", pushSelected);
  document.getElementById("btn-batch-pass").addEventListener("click", () => batchDecide("PASS"));
  document.getElementById("btn-batch-reject").addEventListener("click", () => batchDecide("REJECT"));
}

async function loadSummary() {
  try {
    const s = await api.summary();
    const warnCnt = pendingData.filter((r) => r.validation_status === "WARN").length;
    const errCnt = pendingData.filter((r) => r.validation_status === "FAIL" || r.exception_type).length;
    document.getElementById("stat-0").innerHTML = `${ui.fmtInt(s.pending_review)}<small> 笔</small>`;
    document.getElementById("stat-1").innerHTML = `${ui.fmtInt(s.today_reviewed)}<small> 笔</small>`;
    document.getElementById("stat-2").innerHTML = `${ui.fmtInt(s.today_pushed)}<small> 笔</small>`;
    document.getElementById("stat-3").innerHTML = `${(s.auto_pass_rate * 100).toFixed(1)}<small>%</small>`;
    document.getElementById("stat-d-0").textContent = warnCnt + errCnt ? `其中低置信 ${warnCnt} · 异常 ${errCnt}` : "规则内自动通过";
    document.getElementById("stat-d-1").textContent = `累计通过 ${ui.fmtInt(s.passed_total)} 笔`;
    document.getElementById("stat-d-2").textContent = "凭证已生成 · 全部钩稽通过";
    document.getElementById("stat-d-3").textContent = `自动通过 ${ui.fmtInt(s.auto_passed)} / ${ui.fmtInt(s.passed_total)} 笔`;
    const b = document.getElementById("nav-badge-review");
    if (b) b.textContent = s.pending_review > 0 ? ui.fmtInt(s.pending_review) : "";
  } catch (e) { /* summary 失败不阻塞队列 */ }
}

async function loadPending() {
  document.getElementById("review-tbody").innerHTML = `<tr><td colspan="11">${ui.loadingHtml()}</td></tr>`;
  try {
    pendingData = await api.pending();
    selected.clear();
    document.getElementById("chk-all").checked = false;
    populateFilters();
    renderRows();
    refreshBatchState();
    loadSummary();
  } catch (e) {
    document.getElementById("review-tbody").innerHTML = `<tr><td colspan="11">${ui.emptyHtml("加载失败：" + e.message)}</td></tr>`;
  }
}

function populateFilters() {
  const banks = [...new Set(pendingData.map((r) => r.bank_name).filter(Boolean))];
  const accts = [...new Set(pendingData.map((r) => r.account_name).filter(Boolean))];
  const bk = document.getElementById("f-bank");
  const ac = document.getElementById("f-acct");
  bk.innerHTML = `<option value="">全部银行</option>` + banks.map((b) => `<option>${ui.esc(b)}</option>`).join("");
  ac.innerHTML = `<option value="">全部账户</option>` + accts.map((a) => `<option>${ui.esc(a)}</option>`).join("");
}

function filteredRows() {
  const q = (document.getElementById("f-search").value || "").trim().toLowerCase();
  const dv = document.getElementById("f-date").value;
  const sv = document.getElementById("f-status").value;
  const bv = document.getElementById("f-bank").value;
  const av = document.getElementById("f-acct").value;
  return pendingData.filter((r) => {
    if (sv && r.process_status !== sv) return false;
    if (dv && String(r.txn_date).slice(0, 10) !== dv) return false;
    if (bv && r.bank_name !== bv) return false;
    if (av && r.account_name !== av) return false;
    if (q) {
      const hay = [r.txn_no, r.counterparty_name, r.summary].filter(Boolean).join(" ").toLowerCase();
      if (!hay.includes(q)) return false;
    }
    return true;
  });
}

function renderRows() {
  const rows = filteredRows();
  const tbody = document.getElementById("review-tbody");
  if (rows.length === 0) {
    tbody.innerHTML = `<tr><td colspan="11">${ui.emptyHtml("暂无待复核流水")}</td></tr>`;
    return;
  }
  tbody.innerHTML = rows.map((r) => `
    <tr data-id="${r.record_id}" class="${selected.has(r.record_id) ? "checked" : ""}">
      <td><label class="ck"><input type="checkbox" class="row-chk" data-id="${r.record_id}" ${selected.has(r.record_id) ? "checked" : ""} /></label></td>
      <td class="mono">${ui.esc(r.txn_no)}</td>
      <td class="num">${ui.fmtDate(r.txn_date)}</td>
      <td>${dirHtml(r.dc_flag)}</td>
      <td class="num">${amtHtml(r.dc_flag, r.amount)}</td>
      <td>${ui.esc(r.counterparty_name || "—")}</td>
      <td>${ui.esc(r.account_name || "—")}</td>
      <td style="max-width:200px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${r.summary ? ui.esc(r.summary) : '<span style="color:var(--muted)">—</span>'}</td>
      <td>${ui.validationBadge(r.validation_status)}</td>
      <td>${ui.statusBadge(r.process_status)}</td>
      <td><button class="link-btn row-open" data-id="${r.record_id}">详情</button></td>
    </tr>`).join("");

  tbody.querySelectorAll("tr[data-id]").forEach((tr) => {
    tr.addEventListener("click", (e) => {
      if (e.target.closest(".row-chk") || e.target.closest(".row-open")) return;
      openRecordDrawer(Number(tr.dataset.id), { onChanged: reload });
    });
  });
  tbody.querySelectorAll(".row-chk").forEach((chk) => {
    chk.addEventListener("change", (e) => {
      const id = Number(chk.dataset.id);
      if (chk.checked) selected.add(id); else selected.delete(id);
      renderRows();
      refreshBatchState();
    });
  });
  tbody.querySelectorAll(".row-open").forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.stopPropagation();
      openRecordDrawer(Number(btn.dataset.id), { onChanged: reload });
    });
  });
}

function refreshBatchState() {
  const n = selected.size;
  document.getElementById("btn-batch-pass").disabled = n === 0;
  document.getElementById("btn-batch-reject").disabled = n === 0;
}

async function reload() {
  await Promise.all([loadSummary(), loadPending()]);
}

async function batchDecide(result) {
  if (selected.size === 0) return;
  const ids = Array.from(selected);
  if (result === "REJECT") {
    const reason = await ui.promptModal({ title: "批量驳回", placeholder: `将对 ${ids.length} 笔流水驳回，请填写原因（必填）`, okText: "确认驳回", danger: true });
    if (reason === null) return;
    if (!reason) { ui.toast("驳回原因不能为空", "error"); return; }
    try {
      await api.decideBatch(ids, "REJECT", reason);
      ui.toast(`已驳回 ${ids.length} 笔`, "info");
      await reload();
    } catch (e) { ui.toast(e.message, "error"); }
    return;
  }
  ui.confirmModal({
    title: "批量通过",
    html: `<p>确认将通过 <b>${ids.length}</b> 笔待复核流水，并入账队列？</p>`,
    okText: "确认通过",
    onOk: async () => {
      await api.decideBatch(ids, "PASS");
      ui.toast(`已通过 ${ids.length} 笔`, "success");
      await reload();
    },
  });
}

async function pushSelected() {
  if (selected.size === 0) { ui.toast("请先勾选要推送的流水", "error"); return; }
  const ids = Array.from(selected);
  const total = pendingData.filter((r) => ids.includes(r.record_id)).reduce((s, r) => s + Number(r.amount), 0);
  ui.confirmModal({
    title: "确认推送金蝶",
    danger: true,
    okText: "确认推送",
    html: `<p>即将推送 <b>${ids.length}</b> 笔流水至金蝶云星空并自动制证，合计金额 <b>${ui.fmtAmount(total)}</b>。</p>
      <div class="sum">对账钩稽：全部通过 ▸ 可推送<br>推送后生成凭证号并回写溯源关联</div>`,
    onOk: async () => {
      await api.decideBatch(ids, "PASS");
      for (const id of ids) { try { await api.pushRecord(id); } catch (e) { /* 单笔失败不中断 */ } }
      ui.toast(`已推送 ${ids.length} 笔至金蝶 · 凭证已生成并回写溯源`, "success");
      await reload();
    },
  });
}

// 共享：流水详情抽屉（契约字段 / 校验 / 溯源 / 留痕）+ 状态机操作按钮
import { api } from "./api.js";
import * as ui from "./ui.js";

const RULE_LABEL = {
  R001: "重复流水", R002: "负金额/方向非法", R003: "缺字段",
  R004: "超阈值", R005: "币种异常",
};

function field(k, v) {
  return `<div class="field"><span class="k">${ui.esc(k)}</span><span class="v">${v}</span></div>`;
}

function amtSpan(dc, amount) {
  const c = dc === "C" ? "in" : "out";
  const sgn = dc === "C" ? "+" : "−";
  return `<span class="amt ${c}">${sgn}¥ ${ui.money(amount)}</span>`;
}

function renderTrace(tr) {
  const f = tr.flow || {};
  const bank = tr.bank || {};
  const account = tr.account || {};
  const batch = tr.batch || {};

  const dir = f.dc_flag === "C" ? "收（贷方）" : f.dc_flag === "D" ? "付（借方）" : "—";
  const fieldsHtml = [
    field("唯一流水号", `<span class="mono">${ui.esc(f.txn_no || "—")}</span>`),
    field("交易日期", ui.fmtDate(f.txn_date)),
    field("交易时间", ui.esc(f.txn_time || "—")),
    field("借贷方向", dir),
    field("金额", amtSpan(f.dc_flag, f.amount)),
    field("币种", ui.esc(f.currency || "CNY")),
    field("对方户名", ui.esc(f.counterparty_name || "—")),
    field("对方账号", ui.esc(f.counterparty_account || "—")),
    field("本方账户", ui.esc(account.account_name ? `${account.account_name}（${account.account_no}）` : (account.account_no || "—"))),
    field("摘要", f.summary ? ui.esc(f.summary) : '<span style="color:var(--muted)">缺失</span>'),
  ].join("");

  const validations = tr.validations || [];
  let vHtml;
  if (validations.length === 0) {
    vHtml = `<div class="muted" style="font-size:13px">无校验记录</div>`;
  } else {
    vHtml = validations.map((v) => {
      const map = { PASS: ["通过", "var(--ok)"], WARN: ["告警", "var(--warn)"], FAIL: ["异常", "var(--danger)"] };
      const [label, color] = map[v.rule_result] || ["—", "var(--muted)"];
      const rule = RULE_LABEL[v.rule_code] ? `${v.rule_code} · ${RULE_LABEL[v.rule_code]}` : v.rule_code;
      return `<div class="trace-item">
        <span class="t">${ui.esc(rule)}</span>
        <span class="c"><span style="color:${color};font-weight:600">${label}</span>${v.error_detail ? `<div class="muted" style="margin-top:3px;font-size:12px">${ui.esc(v.error_detail)}</div>` : ""}</span>
      </div>`;
    }).join("");
  }

  const traceHtml = [
    ["来源银行", bank.bank_name ? `${ui.esc(bank.bank_name)}（${ui.esc(bank.bank_code)}）` : "—"],
    ["来源账户", account.account_no ? `${ui.esc(account.account_name || "")} ${ui.esc(account.account_no)}` : "—"],
    ["采集批次", `${ui.esc(batch.batch_no || "—")} <span class="tag-mini">${ui.esc(batch.source_type || "")}</span>`],
    ["记录 ID", `<span class="mono">${ui.esc(String(f.record_id ?? "—"))}</span>`],
    ["去重指纹", `<span class="mono" style="font-size:12px;word-break:break-all">${ui.esc(f.dedup_key || "—")}</span>`],
  ].map(([k, v]) => `<div class="trace-item"><span class="t">${k}</span><span class="c">${v}</span></div>`).join("");

  // 操作留痕时间线
  const events = [];
  events.push({ cls: "green", who: "系统", act: `采集落库 · 校验预筛`, tm: batch.imported_at ? ui.fmtDateTime(batch.imported_at) : "—", desc: batch.source_type ? `源：${batch.source_type} · 批次 ${batch.batch_no || "—"}` : "" });
  (tr.reviews || []).forEach((rv) => {
    const cls = rv.review_result === "PASS" ? "green" : rv.review_result === "ADJUST" ? "" : "reject";
    events.push({ cls, who: rv.reviewer || "复核员", act: `人工复核 · ${rv.review_result}`, tm: ui.fmtDateTime(rv.review_time), desc: [rv.matched_subject, rv.comment].filter(Boolean).join(" · ") });
  });
  (tr.pushes || []).forEach((p) => {
    events.push({ cls: p.push_status === "SUCCESS" ? "green" : "", who: p.pushed_by || "系统", act: `推送金蝶 · ${p.push_status}`, tm: ui.fmtDateTime(p.pushed_at), desc: p.voucher_no ? `凭证号 ${p.voucher_no}` : (p.error_msg || "") });
  });
  events.sort((a, b) => (a.tm || "").localeCompare(b.tm || ""));
  const audit = events.map((e) => `
    <div class="it ${e.cls}">
      <div class="who">${ui.esc(e.who)}</div>
      <div class="act">${ui.esc(e.act)}</div>
      <div class="tm">${ui.esc(e.tm)}${e.desc ? " · " + ui.esc(e.desc) : ""}</div>
    </div>`).join("");

  return { fieldsHtml, vHtml, traceHtml, audit, flow: f };
}

export function openRecordDrawer(record_id, { onChanged } = {}) {
  ui.openDrawer({ title: "流水详情", body: ui.loadingHtml("加载详情…") });
  api.traceByRecord(record_id).then((tr) => {
    const f = tr.flow || {};
    const { fieldsHtml, vHtml, traceHtml, audit } = renderTrace(tr);

    document.getElementById("dw-title").textContent = `流水详情 · #${record_id}`;
    document.getElementById("dw-badge").innerHTML = ui.statusBadge(f.process_status);
    document.getElementById("dw-body").innerHTML = `
      <div class="section-title">契约字段 · 统一流水契约</div>
      <div class="field-grid">${fieldsHtml}</div>

      <div class="section-title">校验结果</div>
      ${vHtml}

      <div class="section-title">数据溯源</div>
      <div class="trace-list">${traceHtml}</div>

      <div class="section-title">操作留痕 · 审计日志</div>
      <div class="audit">${audit || '<div class="muted" style="font-size:13px">无记录</div>'}</div>`;

    bindFooter(f, record_id, onChanged);
  }).catch((e) => {
    document.getElementById("dw-body").innerHTML = ui.emptyHtml("加载失败：" + e.message);
    document.getElementById("dw-foot").innerHTML = `<button class="btn btn-ghost" id="dw-close-btn">关闭</button>`;
    document.getElementById("dw-close-btn").addEventListener("click", ui.closeDrawer);
  });
}

function bindFooter(f, record_id, onChanged) {
  const s = f.process_status;
  const foot = document.getElementById("dw-foot");
  const closeBtn = `<button class="btn btn-ghost" data-act="close">取消</button>`;

  const doPass = (andPush) => async () => {
    try {
      if (s === "REVIEW_READY") await api.decide(record_id, "PASS");
      ui.toast("已通过复核", "success");
      if (andPush) await doPushOnce(record_id, onChanged);
      else { ui.closeDrawer(); onChanged && onChanged(); }
    } catch (e) { ui.toast(e.message, "error"); }
  };
  const doReject = async () => {
    const reason = await ui.promptModal({ title: "驳回流水", placeholder: "请填写驳回原因（必填，用于审计留痕）", okText: "确认驳回", danger: true });
    if (reason === null) return;
    if (!reason) { ui.toast("驳回原因不能为空", "error"); return; }
    try {
      await api.decide(record_id, "REJECT", null, reason);
      ui.toast("已驳回", "info");
      ui.closeDrawer();
      onChanged && onChanged();
    } catch (e) { ui.toast(e.message, "error"); }
  };
  const doPush = async () => {
    if (s === "REVIEW_READY") {
      try { await api.decide(record_id, "PASS"); } catch (e) { ui.toast(e.message, "error"); return; }
    }
    await doPushOnce(record_id, onChanged);
  };

  if (s === "REVIEW_READY") {
    foot.innerHTML = `
      <button class="btn btn-danger" data-act="reject">驳回</button>
      ${closeBtn}
      <button class="btn btn-ok" data-act="pass-push">通过并入账</button>
      <button class="btn btn-pri" data-act="push">推送金蝶</button>`;
  } else if (s === "REVIEW_PASSED") {
    foot.innerHTML = `${closeBtn}<button class="btn btn-pri" data-act="push">推送金蝶</button>`;
  } else {
    foot.innerHTML = closeBtn;
  }

  foot.querySelector('[data-act="reject"]')?.addEventListener("click", doReject);
  foot.querySelector('[data-act="pass-push"]')?.addEventListener("click", doPass(true));
  foot.querySelector('[data-act="push"]')?.addEventListener("click", doPush);
  foot.querySelector('[data-act="close"]')?.addEventListener("click", ui.closeDrawer);
}

async function doPushOnce(record_id, onChanged) {
  const p = await api.pushRecord(record_id);
  ui.toast(`推送成功，凭证号 ${p.voucher_no || "—"}`, "success");
  ui.closeDrawer();
  onChanged && onChanged();
}

// 通用 UI 工具：格式化、状态徽章、toast、弹窗、抽屉、HTML 转义
// 类名与静态容器（#modal-wrap/#modal、#mask/#drawer、#toast）对齐 UI 原型

export function esc(s) {
  if (s === null || s === undefined) return "";
  return String(s).replace(/[&<>"']/g, (c) => ({
    "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;",
  }[c]));
}

export function fmtAmount(v, currency = "CNY") {
  const n = Number(v || 0);
  const sym = currency === "CNY" ? "¥" : currency + " ";
  return sym + n.toLocaleString("zh-CN", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

export function money(n) {
  return Number(n || 0).toLocaleString("zh-CN", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

export function fmtInt(n) {
  return Number(n || 0).toLocaleString("zh-CN");
}

export function fmtDate(s) {
  if (!s) return "—";
  return String(s).slice(0, 10);
}

export function fmtDateTime(s) {
  if (!s) return "—";
  return String(s).replace("T", " ").slice(0, 19);
}

export function dcFlagText(dc) {
  return dc === "C" ? "收" : dc === "D" ? "支" : (dc || "—");
}

// 处理状态徽章（对齐设计归档六态 + 原型色板）
const STATUS_MAP = {
  REVIEW_READY: ["b-wait", "待复核"],
  REVIEW_PASSED: ["b-pass", "自动通过"],
  KINGDEE_POSTED: ["b-push", "已推送"],
  PUSHED: ["b-push", "已推送"],
  REJECTED: ["b-reject", "已驳回"],
  LOADED: ["b-doing", "已入库"],
  VALIDATING: ["b-doing", "校验中"],
};

export function statusBadge(status) {
  const [cls, label] = STATUS_MAP[status] || ["b-reject", status || "—"];
  return `<span class="badge ${cls}">${esc(label)}</span>`;
}

// 校验结果徽章（流水级 aggregation）
export function validationBadge(status) {
  const map = {
    PASS: ["b-pass", "校验通过"],
    WARN: ["b-wait", "需复核"],
    FAIL: ["b-err", "校验异常"],
    PENDING: ["b-reject", "待校验"],
  };
  const [cls, label] = map[status] || ["b-reject", status || "—"];
  return `<span class="badge ${cls}">${esc(label)}</span>`;
}

export function ruleBadge(rule_code) {
  return `<span class="badge b-doing">${esc(rule_code)}</span>`;
}

// ---------- toast ----------
let _tt = null;
export function toast(msg, type = "info", ms = 2800) {
  const t = document.getElementById("toast");
  if (!t) return;
  t.textContent = msg;
  t.className = type === "success" ? "on ok" : type === "error" ? "on err" : "on info";
  clearTimeout(_tt);
  _tt = setTimeout(() => t.classList.remove("on"), ms);
}

// ---------- 弹窗（静态容器）----------
export function closeModal() {
  const w = document.getElementById("modal-wrap");
  if (w) w.classList.remove("on");
}

function openModal({ icon = "ok", title = "", sub = "", body = "", actions = "" }) {
  document.getElementById("mo-title").textContent = title;
  document.getElementById("mo-sub").textContent = sub || "";
  const ic = document.getElementById("mo-ic");
  const glyphs = { warn: "⚠", ok: "✓", danger: "!" };
  ic.className = "ic " + icon;
  ic.innerHTML = glyphs[icon] || "✓";
  document.getElementById("mo-body").innerHTML = body || "";
  document.getElementById("mo-ft").innerHTML = actions || "";
  document.getElementById("modal-wrap").classList.add("on");
  return { close: closeModal, el: document.getElementById("modal") };
}

export function confirmModal({ title, html, okText = "确认", danger = false, onOk }) {
  const okCls = danger ? "btn-danger" : "btn-pri";
  openModal({
    icon: danger ? "warn" : "ok",
    title,
    sub: danger ? "该操作为不可逆入账动作，请二次确认" : "",
    body: html || "",
    actions: `<button class="btn btn-ghost" data-cancel>取消</button><button class="btn ${okCls}" data-ok>${esc(okText)}</button>`,
  });
  const ft = document.getElementById("mo-ft");
  ft.querySelector("[data-cancel]").onclick = closeModal;
  ft.querySelector("[data-ok]").onclick = async () => {
    const okBtn = ft.querySelector("[data-ok]");
    okBtn.disabled = true;
    try {
      await onOk();
      closeModal();
    } catch (e) {
      okBtn.disabled = false;
      toast(e.message || "操作失败", "error");
    }
  };
}

export function promptModal({ title, placeholder, okText = "确认", danger = false }) {
  return new Promise((resolve) => {
    openModal({
      icon: danger ? "danger" : "ok",
      title,
      body: `<textarea class="field" data-input placeholder="${esc(placeholder)}"></textarea>`,
      actions: `<button class="btn btn-ghost" data-cancel>取消</button><button class="btn ${danger ? "btn-danger" : "btn-pri"}" data-ok>${esc(okText)}</button>`,
    });
    const ft = document.getElementById("mo-ft");
    const input = document.getElementById("mo-body").querySelector("[data-input]");
    ft.querySelector("[data-cancel]").onclick = () => { closeModal(); resolve(null); };
    ft.querySelector("[data-ok]").onclick = () => { const v = input.value.trim(); closeModal(); resolve(v); };
    input && input.focus();
  });
}

// ---------- 抽屉（静态容器）----------
export function closeDrawer() {
  document.getElementById("mask")?.classList.remove("on");
  document.getElementById("drawer")?.classList.remove("on");
}

export function openDrawer({ title = "流水详情", badge = "", body = "", footer = "" }) {
  document.getElementById("dw-title").textContent = title;
  document.getElementById("dw-badge").innerHTML = badge || "";
  document.getElementById("dw-body").innerHTML = body;
  document.getElementById("dw-foot").innerHTML = footer || "";
  document.getElementById("mask").classList.add("on");
  document.getElementById("drawer").classList.add("on");
  return { close: closeDrawer, el: document.getElementById("drawer") };
}

export function loadingHtml(text = "加载中…") {
  return `<div class="loading"><div class="spinner"></div>${esc(text)}</div>`;
}

export function emptyHtml(text = "暂无数据") {
  return `<div class="empty">${esc(text)}</div>`;
}

// 静态容器事件绑定（模块加载即绑定一次）
document.getElementById("dw-close")?.addEventListener("click", closeDrawer);
document.getElementById("mask")?.addEventListener("click", closeDrawer);
document.getElementById("modal-wrap")?.addEventListener("click", (e) => {
  if (e.target && e.target.id === "modal-wrap") closeModal();
});
document.addEventListener("keydown", (e) => {
  if (e.key === "Escape") { closeDrawer(); closeModal(); }
});
